  model.invoke.mockImplementation(async()=>({modelId:'gpt-6-luna',output:{facts:[...(!options.factKind?[{id:'rate',kind:options.paymentClaim?'payment_claim':'rate_claim',disclosure:'guest',source,value:{amount,currency:'ZAR',...(options.paymentClaim?{status:'claimed_paid'}:{basis}),...(options.roomRef?{roomRef:options.roomRef}:{})}}]:[]),...(options.scopeFacts?[{id:'board',kind:options.factKind??'board',disclosure:'guest',source,value:options.factKind==='dates'?{arrival:'2026-11-01',departure:'2026-11-03'}:options.factKind==='party'?'Original Organization':'breakfast'}]:[])],tasks:[{id:'quote',kind:'quote',factIds:options.omitClaimReference||options.wrongFactTask?[]:options.scopeFacts?['rate','board']:['rate'],source:options.wrongFactTask?{...source,quote:text.slice(0,text.indexOf(' Is parking')),end:text.indexOf(' Is parking')}:source},...(options.wrongFactTask?[{id:'other',kind:'question',factIds:options.factKind?['board']:options.scopeFacts?['rate','board']:['rate'],source:{...source,quote:'Is parking available?',start:text.indexOf('Is parking')}}]:[])],unresolvedAsks:[]},usage:{inputTokens:1,outputTokens:1,totalTokens:2,latencyMs:1,estimatedCostUsd:0,rateTableVersion:'test'}}));
  const revision=await syntheticRevision(options.amounts??['1560.00']);
  const {quoteDigest}=await import('../src/quote-proposal/quote-revision.js');
  const bind=vi.fn(async(ctx:any,r:any,claim:any)=>{if(options.bindingError)throw new Error('source unreachable');if(options.mutateClaim){claim.value.amount='1560.00';claim.amountCents=156000;}return options.binding===null?null:({claimFactId:claim.id,claimDigest:quoteDigest(claim),sourceDigest:quoteDigest(claim.source),revisionId:r.id,authorizationId:r.authorizationId,scopeDigest:r.scopeDigest,requestId:ctx.input.requestId,ownerRef:ctx.input.authorizationScope.ownerRef,threadId:ctx.input.authorizationScope.threadId,evaluatedAt:ctx.input.clock.sourceAt,groupIds:['g1'],taxBasis:'gross_included',evidenceRefs:['authorized-claim-scope'],...options.binding});});
  const imported=options.sourceOffer?await (await import('../src/quote-proposal/quote-revision.js')).resolveImportedOffer({ref:'imported',authorizationId:'auth',evaluationAt:input.clock.sourceAt,resolveSource:async()=>({ref:'imported',sourceHash:'a'.repeat(64),authorizationId:'auth',scopeDigest:'b'.repeat(64),propertyCode:'HRCEN',currency:'ZAR',printedDate:'2026-10-03',sentAt:'2026-10-03T10:00:00Z',validUntil:'2026-10-05',sourceFreshness:{authorizationId:'auth',sourceRefs:['imported'],purpose:'offer_source' as const,observedAt:'2026-10-04T08:00:00Z',expiresAt:'2026-10-05T12:00:00Z'},terms:'Synthetic original total',lines:[{id:'line',page:1,quote:'ZAR 3120.00 total',amount:'3120.00'}]}),authorizeSource:async()=>true}):null;
  const converter=vi.fn(async()=>new Response('%PDF-1.4 synthetic',{headers:{'content-type':'application/pdf'}}));
  const factory=createReservationistDependencies({adapter:model,admissions:[],header,converter:{url:'http://local.test',fetchImpl:converter as any},services:{...(imported?{resolveSourceOffer:async()=>imported,...(options.sourceBinding?{authorizeSourceRateClaimBinding:async(ctx:any,offer:any,claim:any)=>({claimFactId:claim.id,claimDigest:quoteDigest(claim),sourceDigest:quoteDigest(claim.source),revisionId:offer.id,authorizationId:offer.authorizationId,scopeDigest:offer.scopeDigest,requestId:ctx.input.requestId,ownerRef:ctx.input.authorizationScope.ownerRef,threadId:ctx.input.authorizationScope.threadId,evaluatedAt:ctx.input.clock.sourceAt,taxBasis:'gross_included',targetTaxBasis:'gross_included',evidenceRefs:['source-total-scope']})}:{}),authorizeSourceOffer:async(ctxSource:any,ctx:any,_signal:any)=>{if(options.attestationMutates)ctx.facts[0].value.amount='3100.00';return ({sourceDigest:quoteDigest(ctxSource),requestId:ctx.input.requestId,ownerRef:ctx.input.authorizationScope.ownerRef,threadId:ctx.input.authorizationScope.threadId,scopeDigest:ctxSource.scopeDigest,evaluatedAt:ctx.input.clock.sourceAt});}}:{}),authorizeGuestProposal:async()=>true,...(!options.omitBinding?{authorizeRateClaimBinding:bind}:{}),resolveQuoteTask:async()=>({propertyCode:'HRCEN',authoredDate:'2026-10-04',selections:[{sourceRef:'synthetic',groupId:'g1',optionId:'selected'}],resolveSource:async()=>sourceFromRevision(revision),resolvePolicy:async()=>({ref:'synthetic-policy',propertyCode:'HRCEN',sourceHashes:['b'.repeat(64)],authoredDates:['2026-09-26'],families:[{rateCode:'BAR',board:'room_only'}],vat:'included',levy:'included'}),admission:{authorizationId:revision.authorizationId,sourceEvaluationAt:'2026-10-04T10:00:00Z',maxSourceAgeMs:3600000,expectedRequests:{synthetic:sourceFromRevision(revision).request},authorizeSource:async()=>true}})} as any});
