  const evidence={requestId:input.requestId,ownerRef:input.authorizationScope.ownerRef,threadId:bad==='scope'?'other':input.authorizationScope.threadId,authorizationId:'grant',propertyCode:input.propertyCode,reservationRef:actionInput.reservationRef,...(kind==='cancel_request'?{resolvedConfirmation:'ABC123'}:{}),sourceRef:'detail:ABC123',sourceHash:'a'.repeat(64),observedAt:at,expiresAt:'2026-10-04T11:00:00Z',maxSourceAgeMs:3600000,current:{arrivalDate:'2026-10-12',departureDate:'2026-10-14'},requestSource:{sourceRef:source.attachmentId,sourceHash:bad==='request'?'b'.repeat(64):hash,observedAt:at,taskId:'action',changes:actionInput.changes},...(kind==='cancel_request'?{cancellationReview:{outcome:'prepared_for_human_review' as const,roomScope:{state:'unresolved' as const,complete:false as const},policy:{state:'unknown' as const},fee:{state:'unknown_precommit' as const,amount:null,currency:null},action:{actor:'human' as const,cancellationStarted:false as const,commitAvailable:false as const}}}:{})};
