describe('source-bound requested arrival receipt',()=>{
 async function arrivalCase(bad?:'hash'|'time'|'thread'|'disclosure'|'value'|'span'){
  const text='I will like to check in by 3:00pm.',source={attachmentId:'message:message',sourceHash:createHash('sha256').update(text).digest('hex'),page:1,quote:text,start:0,end:text.length},model=adapter([]);
  model.invoke.mockImplementation(async()=>({modelId:'gpt-6-luna',output:{facts:[],tasks:[{id:'arrival',kind:'question',factIds:[],source}],unresolvedAsks:[]},usage:{inputTokens:1,outputTokens:1,totalTokens:2,latencyMs:1,estimatedCostUsd:0,rateTableVersion:'test'}}));
  const receipt={kind:'requested_arrival_acknowledgement',authority:'customer_claim',hotelPermission:'unverified',taskId:'arrival',requestId:input.requestId,ownerRef:input.authorizationScope.ownerRef,threadId:bad==='thread'?'foreign':input.authorizationScope.threadId,propertyCode:input.propertyCode,triggerMessageId:input.trigger.id,requestedTime:bad==='value'?'14:00':'3:00pm',source:{sourceRef:source.attachmentId,sourceHash:bad==='hash'?'f'.repeat(64):source.sourceHash,quote:text,start:bad==='span'?1:0,end:text.length,observedAt:bad==='time'?'2026-10-05T10:00:00Z':input.trigger.at,disclosure:bad==='disclosure'?'staff_only':'guest'}};
  const factory=createReservationistDependencies({adapter:model,admissions:[],header,converter:{url:'unused'},services:{resolveRequestedArrivalAcknowledgement:async()=>receipt} as unknown as Parameters<typeof createReservationistDependencies>[0]['services']});
  return runReservationistRuntime({...input,messages:[{...input.messages[0],text,disclosure:'guest'}]},factory.dependencies);
 }
 it('accepts only a receipt of the sourced request, without asserting operational approval',async()=>{const r=await arrivalCase();expect(r.tasks[0].status).toBe('complete');expect(r.textBody).toContain('3:00pm');expect(r.textBody).toContain('Staff must verify');expect(r.textBody).not.toMatch(/confirmed|approved|cleared/i);});
 it.each(['hash','time','thread','disclosure','value','span'] as const)('denies %s receipt mismatch',async bad=>{const r=await arrivalCase(bad);expect(r.tasks[0].status).toBe('blocked');expect(r.textBody).not.toContain('We have noted your request');});
});


