 it('retains proof and recorded-payment topics when an exact target has no ledger read',async()=>{const {result,resolve}=await paymentContext({ask:'Please confirm recorded payment for reservation ABC123.'});expect(resolve).toHaveBeenCalledOnce();expect(result.tasks[0].status).toBe('needs_clarification');expect(result.tasks[0].guestText).toMatch(/proof of payment/i);expect(result.tasks[0].guestText).toMatch(/recorded payment/i);expect(result.tasks[0].guestText).toMatch(/ledger/i);expect(result.tasks[0].guestText).toMatch(/unavailable|missing|staff must verify.*applicable source before answering this request/i);expect(result.paymentComparisons![0]).toMatchObject({status:'cannot_check',cleared:false,recordedMinor:null});expect(result.preparedFacts).toEqual([]);expect(result.packets).toEqual([]);expect(result.readReceipts).toEqual([]);});
