describe('normal missing-state amendment focus',()=>{
 const asks=['Alex Example – amended to 1 night’s stay','Group B – removed from list','Jamie Example – (added) 1 x Twin Room'];
 async function run(ask:string,incomplete=false,options:{prefix?:string;staff?:boolean;prior?:boolean;kind?:string;mutateScope?:boolean}={}){
  const text=(options.prefix??'')+ask,sourceId=options.prior?'old':'message',source={attachmentId:`message:${sourceId}`,sourceHash:createHash('sha256').update(text).digest('hex'),page:1,quote:ask,start:text.indexOf(ask),end:text.indexOf(ask)+ask.length},kind=options.kind??'change',tasks=[{id:'amendment',kind,factIds:[],source}],model=adapter([]),invoke=vi.fn(async():Promise<ModelInvokeResult>=>{if(incomplete&&invoke.mock.calls.length>1)throw new Error('azure_luna_completion_incomplete');return {modelId:'gpt-6-luna',output:{facts:[],tasks:tasks.map(t=>incomplete?{...t,source:{attachmentId:source.attachmentId,sourceHash:source.sourceHash,page:1,quote:ask}}:t),unresolvedAsks:[]},usage:{inputTokens:1,outputTokens:1,totalTokens:2,latencyMs:1,estimatedCostUsd:0,rateTableVersion:'test'}};});
  const state=vi.fn(async()=>{throw new ReservationistTaskEvidenceUnavailable('pending_action_evidence_unavailable',['the reservation reference','current reservation details','requested amendment or cancellation']);}),factory=createReservationistDependencies({adapter:{...model,invoke,reserveCalls:async()=>{}},...(incomplete?{extractionMode:'task_first' as const}:{}),admissions:[],header,converter:{url:'unused'},services:{resolvePendingActionTask:state}}),message={...input.messages[0],id:sourceId,text,...(options.prior?{at:input.clock.sourceAt}:{}),...(options.staff?{disclosure:'staff_only' as const}:{})},scoped={...input,messages:[message,...(options.prior?[{...input.messages[0],text:'Please quote.'}]:[])]};
  if(options.mutateScope){const signal=new AbortController().signal,plan=await factory.dependencies.plan(scoped,signal),work=await factory.dependencies.execute(plan,{...scoped,authorizationScope:{...input.authorizationScope,ownerRef:'foreign'}},signal);return{tasks:work.tasks,state,work};}
  const result=await runReservationistRuntime(scoped,factory.dependencies);return{tasks:result.tasks,state,work:result};
 }
 it.each(asks)('keeps exact requested amendment in normal and incomplete-source clarification: %s',async ask=>{for(const incomplete of [false,true]){const {tasks,state,work}=await run(ask,incomplete);expect(tasks[0].status).toBe('needs_clarification');expect(tasks[0].guestText).toContain(`Requested amendment: “${ask}”`);expect(tasks[0].evidenceRefs).toEqual(['message:message']);if(!incomplete){expect(tasks[0].guestText).toContain('current reservation details');expect(state).toHaveBeenCalledOnce();}else expect(state).not.toHaveBeenCalled();expect(work.packets).toEqual([]);expect(work.artifacts).toEqual([]);expect(work.preparedFacts).toEqual([]);expect(tasks[0].guestText).not.toMatch(/booking is confirmed|changes have been made/);}});
 it.each([{prefix:'Not\n\n'},{prefix:'For another property:\n\n'},{prefix:'Not\n'},{prefix:'If authorized\n'},{prefix:'Begin forwarded message:\n'},{prefix:'> Instruction:\n'},{prefix:'For another property:\n'},{staff:true},{prior:true},{mutateScope:true},{kind:'cancel_request'}])('does not expose an unauthorized or unrelated amendment quote %j',async options=>{const {tasks,work}=await run(asks[0],false,options);expect(tasks[0].guestText).not.toContain('Requested amendment:');expect(work.packets).toEqual([]);expect(work.artifacts).toEqual([]);});
 it('keeps overlong requested amendments bounded instead of truncating original authority',async()=>{const {tasks}=await run('Please amend '+ 'x'.repeat(501));expect(tasks[0].guestText).not.toContain('Requested amendment:');expect(tasks[0].guestText.length).toBeLessThan(500);});
});

